mapper.select:
select TEMP.TMP_C_NAME tmpCName, TEMP.TMP_E_NAME tmpEName, TEMP.DTO_NAME dtoName, DEFINE.INTERF_E_NAME interfName, DEFINE.ORDERNO orderNo, TEMP.TMP_TYPE tmpType, TEMP.SYSTEMID systemid from VAL_INTERF_TEMPLATE TEMP, VAL_INTERF_DEFINE DEFINE WHERE 1=1 AND TEMP.INTERF_ID = DEFINE.INTERF_ID
AND DEFINE.ORDERNO=#{orderNo,jdbcType=VARCHAR}
AND (
DEFINE.INTERF_E_NAME = #{item,jdbcType=VARCHAR}
)

select TEMP.TMP_C_NAME tmpCName, TEMP.TMP_E_NAME tmpEName, DEFINE.ORDERNO orderNo, TEMP.TMP_TYPE tmpType, INFO.COL_C_NAME colCName, INFO.COL_E_NAME colEName, INFO.COL_TYPE colType, INFO.IS_NULL isNull, INFO.MAX_LENGTH maxLength, INFO.IS_EXIST isExist
,INFO.DICT_CODE AS dictCode
from VAL_INTERF_TEMPLATE TEMP INNER JOIN VAL_INTERF_DEFINE DEFINE ON TEMP.INTERF_ID = DEFINE.INTERF_ID INNER JOIN VAL_TEMP_COL_CHECK_INFO INFO ON INFO.TMP_E_NAME=TEMP.TMP_E_NAME WHERE TEMP.TMP_E_NAME=#{tmpEName,jdbcType=VARCHAR}
